<?php
require_once __DIR__ . '/../config/bootstrap.php';
verify_csrf();
$page = $_GET['page'] ?? 'home';
$allowed = ['home','login','dashboard','flats','residents','bills','payments','complaints','notices','expenses','reports','logout'];
if (!in_array($page,$allowed,true)) $page='home';
if ($page==='logout') { $_SESSION=[]; session_destroy(); header('Location: index.php'); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $action=$_POST['action']??'';
  try {
    if ($action==='login') {
      $stmt=db()->prepare('SELECT id,username,email,password_hash,role,full_name FROM users WHERE username=? OR email=? LIMIT 1');
      $stmt->execute([trim($_POST['username']??''),trim($_POST['username']??'')]); $u=$stmt->fetch();
      if (!$u || !password_verify($_POST['password']??'', $u['password_hash'])) throw new RuntimeException('Invalid username or password.');
      session_regenerate_id(true); unset($u['password_hash']); $_SESSION['user']=$u; redirect('dashboard');
    }
    require_login(); $me=user(); $pdo=db();
    if ($action==='add_flat') { require_admin(); $q=$pdo->prepare('INSERT INTO flats(flat_number,building_block,floor,flat_type,maintenance_rate,status) VALUES(?,?,?,?,?,?)'); $q->execute([trim($_POST['flat_number']),trim($_POST['building_block']), (int)$_POST['floor'],trim($_POST['flat_type']), (float)$_POST['maintenance_rate'],$_POST['status']]); flash('Flat added successfully.'); redirect('flats'); }
    if ($action==='add_resident') { require_admin(); $pdo->beginTransaction(); $check=$pdo->prepare("SELECT id FROM flats WHERE id=? AND status='Vacant' FOR UPDATE"); $check->execute([(int)($_POST['flat_id']??0)]); if(!$check->fetchColumn()) throw new RuntimeException('Choose a vacant flat.'); $q=$pdo->prepare('INSERT INTO users(username,email,password_hash,role,full_name,phone) VALUES(?,?,? ,\'resident\',?,?)'); $q->execute([trim($_POST['username']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT),trim($_POST['full_name']),trim($_POST['phone'])]); $uid=(int)$pdo->lastInsertId(); $flat=(int)$_POST['flat_id']; $q=$pdo->prepare('INSERT INTO residents(user_id,flat_id,full_name,phone,email,joining_date) VALUES(?,?,?,?,?,CURDATE())'); $q->execute([$uid,$flat,trim($_POST['full_name']),trim($_POST['phone']),trim($_POST['email'])]); $pdo->prepare("UPDATE flats SET status='Occupied' WHERE id=?")->execute([$flat]); $pdo->commit(); flash('Resident account created.'); redirect('residents'); }
    if ($action==='generate_bills') { require_admin(); $month=$_POST['billing_month']; $due=$_POST['due_date']; $q=$pdo->query("SELECT id,maintenance_rate FROM flats WHERE status='Occupied'"); $ins=$pdo->prepare("INSERT IGNORE INTO maintenance_bills(bill_no,flat_id,billing_month,amount,due_date,status,notes) VALUES(?,?,?,?,?,'Pending','Monthly maintenance')"); foreach($q as $f)$ins->execute(['BILL-'.$month.'-'.$f['id'],$f['id'],$month,$f['maintenance_rate'],$due]); flash('Monthly bills generated. Existing bills were not duplicated.'); redirect('bills'); }
    if ($action==='pay_bill') { $billId=(int)$_POST['bill_id']; $q=$pdo->prepare("SELECT b.*,f.id flat_id,r.id resident_id FROM maintenance_bills b JOIN flats f ON f.id=b.flat_id LEFT JOIN residents r ON r.flat_id=f.id WHERE b.id=?".($me['role']==='resident'?' AND r.user_id=?':'')); $params=[$billId]; if($me['role']==='resident')$params[]=$me['id']; $q->execute($params); $b=$q->fetch(); if(!$b)throw new RuntimeException('Bill not found or access denied.'); if($b['status']==='Paid')throw new RuntimeException('This bill is already paid.'); $pdo->beginTransaction(); $receipt='RCT-'.date('YmdHis').'-'.random_int(100,999); $q=$pdo->prepare('INSERT INTO payments(receipt_no,bill_id,resident_id,amount,payment_method,transaction_id,remarks,status) VALUES(?,?,?,?,?,?,?,\'Success\')'); $q->execute([$receipt,$billId,$b['resident_id'],(float)$b['amount']+(float)$b['penalty'],$_POST['payment_method']??'UPI','DEMO-'.bin2hex(random_bytes(4)),'Recorded by society portal (demo)']); $pdo->prepare("UPDATE maintenance_bills SET status='Paid' WHERE id=?")->execute([$billId]); $pdo->commit(); flash('Payment recorded in demo mode. Receipt: '.$receipt); redirect('payments'); }
    if ($action==='add_complaint') { $q=$pdo->prepare('SELECT id,flat_id FROM residents WHERE user_id=?'); $q->execute([$me['id']]); $r=$q->fetch(); if(!$r)throw new RuntimeException('Resident profile is not linked to your account.'); $q=$pdo->prepare('INSERT INTO complaints(resident_id,flat_id,category,subject,description,priority) VALUES(?,?,?,?,?,?)'); $q->execute([$r['id'],$r['flat_id'],trim($_POST['category']),trim($_POST['subject']),trim($_POST['description']),$_POST['priority']]); flash('Complaint submitted.'); redirect('complaints'); }
    if ($action==='update_complaint') { require_admin(); $status=$_POST['status']; if(!in_array($status,['Submitted','Assigned','In Progress','Resolved','Closed'],true))throw new RuntimeException('Invalid complaint status.'); $q=$pdo->prepare('UPDATE complaints SET status=?,admin_remarks=?,resolved_at=IF(?=\'Resolved\',NOW(),resolved_at) WHERE id=?'); $q->execute([$status,trim($_POST['admin_remarks']??''),$status,(int)$_POST['complaint_id']]); flash('Complaint updated.'); redirect('complaints'); }
    if ($action==='add_notice') { require_admin(); $q=$pdo->prepare('INSERT INTO notices(title,message,category,published_date,expiry_date,created_by) VALUES(?,?,?,?,?,?)'); $q->execute([trim($_POST['title']),trim($_POST['message']),trim($_POST['category']),date('Y-m-d'),($_POST['expiry_date']?:null),$me['id']]); flash('Notice published.'); redirect('notices'); }
    if ($action==='add_expense') { require_admin(); $q=$pdo->prepare('INSERT INTO expenses(expense_no,category,description,amount,expense_date,paid_to,payment_method,receipt_ref,created_by) VALUES(?,?,?,?,?,?,?,?,?)'); $q->execute(['EXP-'.date('YmdHis').'-'.random_int(10,99),trim($_POST['category']),trim($_POST['description']),(float)$_POST['amount'],$_POST['expense_date'],trim($_POST['paid_to']),$_POST['payment_method'],trim($_POST['receipt_ref']??''),$me['id']]); flash('Expense recorded.'); redirect('expenses'); }
    throw new RuntimeException('Unknown action.');
  } catch(Throwable $ex) { if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack(); flash($ex instanceof PDOException ? 'Could not save the record. Check required fields and ensure the value is not duplicated.' : $ex->getMessage(),'danger'); redirect($page==='home'?'login':$page); }
}
$flash=$_SESSION['flash']??null; unset($_SESSION['flash']);
function rows(string $sql,array $args=[]): array { $q=db()->prepare($sql);$q->execute($args);return $q->fetchAll(); }
function scalar(string $sql,array $args=[]): float|int { $q=db()->prepare($sql);$q->execute($args);return $q->fetchColumn() ?: 0; }
$me=user(); if(in_array($page,['dashboard','flats','residents','bills','payments','complaints','notices','expenses','reports'],true))require_login();
if($page==='home' && $me)redirect('dashboard');
$title=ucfirst($page==='home'?'Home':$page);
