n><option>Credit/Debit Card</option><option>Cheque</option></select><button class="btn btn-sm btn-success">Record demo payment</button></form><?php else: ?>Paid<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><p class="small-muted">Payments in this starter project are demo records, not real bank or UPI transactions.</p>
