</td><td><?=e($r['full_name'])?> / <?=e($r['flat_number'])?></td><td><?=e($r['priority'])?></td><td><?php if($me['role']==='admin'): ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update_complaint"><input type="hidden" name="complaint_id" value="<?=$r['id']?>"><select class="form-select mb-2" name="status"><?php foreach(['Submitted','Assigned','In Progress','Resolved','Closed'] as $s): ?><option <?=$r['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select><input class="form-control mb-2" name="admin_remarks" placeholder="Admin remarks" value="<?=e($r['admin_remarks'])?>"><button class="btn btn-sm btn-primary">Update</button></form><?php else: ?><?=e($r['status'])?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php elseif($page==='notices'): ?><h2>Society Notices</h2><?php if($me['role']==='admin'): ?><div class="panel"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_notice"><div class="col-md-4"><input class="form-control" name="title" placeholder="Notice title" required></div><div class="col-md-3"><select class="form-select" name="category"><option>General</option><option>Maintenance</option><option>Meeting</option><option>Emergency</option><option>Event</option><option>Rule Update</option></select></div><div class="col-md-3"><input class="form-control" type="date" name="expiry_date"></div><div class="col-12"><textarea class="form-control" name="message" placeholder="Notice details" required></textarea></div><div class="col-12"><button class="btn btn-primary">Publish notice</button></div></form></div><?php endif; ?><?php foreach(rows('SELECT * FROM notices WHERE is_active=1 ORDER BY published_date DESC') as $r): ?><div class="panel"><div class="d-flex justify-content-between"><h5><?=e($r['title'])?></h5><span class="badge text-bg-info"><?=e($r['category'])?></span></div><p><?=nl2br(e($r['message']))?></p><small class="small-muted">Published: <?=e($r['published_date'])?> · Expiry: <?=e($r['expiry_date']?:'Not specified')?></small></div><?php endforeach; ?>
<?php elseif($page==='expenses'): require_admin(); ?><h2>Society Expenses</h2><div class="panel"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_expense"><div class="col-md-3"><input class="form-control" name="category" placeholder="Category" required></div><div class="col-md-3"><input class="form-control" name="description" placeholder="Description" required></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" min="0.01" name="amount" placeholder="Amount ₹" required></div><div class="col-md-2"><input class="form-control" type="date" name="expense_date" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><input class="form-control" name="paid_to" placeholder="Paid to" required></div><div class="col-md-3"><select class="form-select" name="payment_method"><option>Bank Transfer</option><option>UPI</option><option>Cheque</option><option>Cash</option></select></div><div class="col-md-3"><input class="form-control" name="receipt_ref" placeholder="Receipt reference (optional)"></div><div class="col-md-2"><button class="btn btn-primary">Record expense</button></div></form></div><?php $data=rows('SELECT * FROM expenses ORDER BY expense_date DESC'); ?><div class="table-wrap"><table class="table"><thead><tr><th>Expense no.</th><th>Category</th><th>Description</th><th>Amount</th><th>Date</th><th>Paid to</th><th>Method</th></tr></thead><tbody><?php foreach($data as $r): ?><tr><td><?=e($r['expense_no'])?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td>₹<?=e(number_format($r['amount'],2))?></td><td><?=e($r['expense_date'])?></td><td><?=e($r['paid_to'])?></td><td><?=e($r['payment_method'])?></td></tr><?php endforeach; ?></tbody></table></div>
<?php elseif($page==='reports'): require_admin(); ?><h2>Reports</h2><div class="row g-3"><div class="col-md-4"><div class="panel"><h5>Successful collections</h5><h3>₹<?=e(number_format(scalar("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='Success'"),2))?></h3></div></div><div class="col-md-4"><div class="panel"><h5>Outstanding maintenance</h5><h3>₹<?=e(number_format(scalar("SELECT COALESCE(SUM(amount+penalty),0) FROM maintenance_bills WHERE status<>'Paid'"),2))?></h3></div></div><div class="col-md-4"><div class="panel"><h5>Total expenses</h5><h3>₹<?=e(number_format(scalar('SELECT COALESCE(SUM(amount),0) FROM expenses'),2))?></h3></div></div></div><div class="panel"><h5>Complaints by status</h5><?php foreach(rows('SELECT status,COUNT(*) total FROM complaints GROUP BY status') as $r): ?><p class="mb-1"><?=e($r['status'])?>: <strong><?=e($r['total'])?></strong></p><?php endforeach; ?></div>
<?php endif; ?>
</div></main></div><?php endif; ?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="script.js"></script></body></html>
